<script setup lang="ts">import {Head,Link} from '@inertiajs/vue3';import PageHeader from '@/Components/Shared/PageHeader.vue';import StatusBadge from '@/Components/Shared/StatusBadge.vue';import {Button} from '@/components/ui/button';defineProps<{metrics:Record<string,number>;oldest:any[];recent:any[]}>();</script><template><Head title="Support Dashboard"/><div class="space-y-6 p-6"><PageHeader title="Support Dashboard" description="Monitor ticket workload, urgency, and response queues."/><div class="flex gap-2"><Button as-child><Link href="/admin/support/tickets">All Tickets</Link></Button><Button variant="outline" as-child><Link href="/admin/support/tickets?assignee=mine">My Tickets</Link></Button></div><div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-6"><div v-for="(v,k) in metrics" :key="k" class="rounded-lg border bg-card p-4"><p class="text-sm capitalize text-muted-foreground">{{String(k).replaceAll('_',' ')}}</p><p class="mt-2 text-3xl font-semibold">{{v}}</p></div></div><div class="grid gap-6 xl:grid-cols-2"><section v-for="(items,title) in { 'Oldest waiting tickets':oldest,'Recently updated':recent }" :key="title" class="rounded-lg border bg-card"><h2 class="border-b p-4 font-semibold">{{title}}</h2><div class="divide-y"><Link v-for="t in items" :key="t.uuid" :href="`/admin/support/tickets/${t.uuid}`" class="block p-4 hover:bg-muted/40"><div class="flex justify-between gap-3"><div><p class="font-medium">{{t.ticket_number}} · {{t.subject}}</p><p class="text-sm text-muted-foreground">{{t.customer}} · {{t.updated_at}}</p></div><StatusBadge :status="t.status"/></div></Link><p v-if="!items.length" class="p-6 text-muted-foreground">No tickets found.</p></div></section></div></div></template>